class vector3d
{
public:
  float x;
  float y;
  float z;

  vector3d() {}
  vector3d(float x, float y, float z) : x(x), y(y), z(z) {}
  vector3d &operator=(const vector3d &other)
  {
    x = other.x;
    y = other.y;
    z = other.z;
    return *this;
  }
  void normalize();
};

vector3d cross(const vector3d &a, const vector3d &b);

struct vector4d
{
  float x;
  float y;
  float z;
  float w;
};

struct matrix4x4
{
  vector4d x;
  vector4d y;
  vector4d z;
  vector4d w;
};

class po
{
  matrix4x4 m;

public:
  void fixup();
};

void po::fixup()
{
  vector3d new_x(m.x.x,m.y.x,m.z.x);
  vector3d new_y(m.x.y,m.y.y,m.z.y);
  vector3d new_z;

  new_x.normalize();
  new_z = cross(new_x,new_y);
  new_z.normalize();
  new_y = cross(new_z,new_x);
  m.x.x = new_x.x;
  m.y.x = new_x.y;
  m.z.x = new_x.z;
  m.x.y = new_y.x;
  m.y.y = new_y.y;
  m.z.y = new_y.z;
  m.x.z = new_z.x;
  m.y.z = new_z.y;
  m.z.z = new_z.z;
}
